"""Demo: squared spectral energy equals twice the edge count."""
from __future__ import annotations
from typing import List
import math

def symmetric_eigenvalues(m: List[List[float]], it: int = 200, tol: float = 1e-12) -> List[float]:
    n = len(m); a = [r[:] for r in m]
    for _ in range(it):
        off = 0.0; p, q = 0, 1
        for i in range(n):
            for j in range(i+1, n):
                if abs(a[i][j]) > off: off = abs(a[i][j]); p, q = i, j
        if off < tol: break
        th = math.pi/4 if a[p][p]==a[q][q] and a[p][q]>0 else (
            -math.pi/4 if a[p][p]==a[q][q] else 0.5*math.atan2(2*a[p][q], a[p][p]-a[q][q]))
        c, s = math.cos(th), math.sin(th)
        for k in range(n):
            akp, akq = a[k][p], a[k][q]; a[k][p]=c*akp+s*akq; a[k][q]=-s*akp+c*akq
        for k in range(n):
            apk, aqk = a[p][k], a[q][k]; a[p][k]=c*apk+s*aqk; a[q][k]=-s*apk+c*aqk
    return sorted((a[i][i] for i in range(n)), reverse=True)

def path_graph(n: int) -> List[List[int]]:
    adj = [[0]*n for _ in range(n)]
    for i in range(n-1): adj[i][i+1]=adj[i+1][i]=1
    return adj

def edge_count(adj: List[List[int]]) -> int:
    n = len(adj); return sum(adj[i][j] for i in range(n) for j in range(i+1, n))

for n in (4, 6, 8):
    g = path_graph(n)
    eigs = symmetric_eigenvalues([[float(x) for x in r] for r in g])
    print(f"P_{n}: sum lambda^2 = {sum(l*l for l in eigs):.4f}, 2|E| = {2*edge_count(g)}")

"""Demo: for bipartite graphs, E_p^+ = (1/2) * sum |lambda|^p."""
from __future__ import annotations
from typing import List
import math

def symmetric_eigenvalues(m: List[List[float]], it: int = 300, tol: float = 1e-13) -> List[float]:
    n = len(m); a = [r[:] for r in m]
    for _ in range(it):
        off = 0.0; p, q = 0, 1
        for i in range(n):
            for j in range(i+1, n):
                if abs(a[i][j]) > off: off = abs(a[i][j]); p, q = i, j
        if off < tol: break
        if a[p][p]==a[q][q]:
            th = math.pi/4 if a[p][q]>0 else -math.pi/4
        else:
            th = 0.5*math.atan2(2*a[p][q], a[p][p]-a[q][q])
        c, s = math.cos(th), math.sin(th)
        for k in range(n):
            akp, akq = a[k][p], a[k][q]; a[k][p]=c*akp+s*akq; a[k][q]=-s*akp+c*akq
        for k in range(n):
            apk, aqk = a[p][k], a[q][k]; a[p][k]=c*apk+s*aqk; a[q][k]=-s*apk+c*aqk
    return sorted((a[i][i] for i in range(n)), reverse=True)

def complete_bipartite(a: int, b: int) -> List[List[int]]:
    n = a+b; adj = [[0]*n for _ in range(n)]
    for i in range(a):
        for j in range(a, n): adj[i][j]=adj[j][i]=1
    return adj

eigs = symmetric_eigenvalues([[float(x) for x in r] for r in complete_bipartite(3, 3)])
for p in (1.0, 2.0, 2.5, 4.0):
    epos = sum(l**p for l in eigs if l > 1e-9)
    eabs = sum(abs(l)**p for l in eigs if abs(l) > 1e-9)
    print(f"K_3,3 p={p}: E_p^+={epos:.4f}, half-Schatten={0.5*eabs:.4f}")

