function SquaredEnergy(G):
    m <- 0
    for each unordered pair {u,v} of vertices:
        if u adjacent to v: m <- m + 1   # count each edge once
    return 2 * m

function PositivePEnergy(A, p):
    (lambda_1..lambda_n) <- SymmetricEigenvalues(A)
    e <- 0
    for each lambda_i:
        if lambda_i > 0: e <- e + lambda_i^p
    return e

